/* I2C bus: bit-banged via W65C22 VIA port A (shadow-byte RMW). */
#define I2C_SDA_MASK (1u << 0)
#define I2C_SCL_MASK (1u << 1)
static unsigned char _i2c_sh;  /* shadow for BW_VIA_ORA */
#define I2C_SDA_HI() (_i2c_sh |= I2C_SDA_MASK, BW_VIA_ORA = _i2c_sh)
#define I2C_SDA_LO() (_i2c_sh &= (unsigned char)~I2C_SDA_MASK, BW_VIA_ORA = _i2c_sh)
#define I2C_SCL_HI() (_i2c_sh |= I2C_SCL_MASK, BW_VIA_ORA = _i2c_sh)
#define I2C_SCL_LO() (_i2c_sh &= (unsigned char)~I2C_SCL_MASK, BW_VIA_ORA = _i2c_sh)

/* I2C timing: t_LOW ≥ 4.7 µs (100 kHz standard mode). */
static void i2c_delay(void) { unsigned char i; for (i = 0; i < 2; i++) ; }
static void i2c_start(void) { I2C_SDA_HI(); I2C_SCL_HI(); i2c_delay(); I2C_SDA_LO(); i2c_delay(); I2C_SCL_LO(); }
static void i2c_stop(void)  { I2C_SDA_LO(); I2C_SCL_HI(); i2c_delay(); I2C_SDA_HI(); i2c_delay(); }
static void i2c_write(unsigned char dat)
{
    unsigned char i;
    for (i = 0; i < 8; i++) {
        if (dat & 0x80) I2C_SDA_HI(); else I2C_SDA_LO();
        dat <<= 1;
        I2C_SCL_HI(); i2c_delay(); I2C_SCL_LO(); i2c_delay();
    }
    /* ACK clock — we do not check the ACK (write-only devices). */
    I2C_SDA_HI(); I2C_SCL_HI(); i2c_delay(); I2C_SCL_LO(); i2c_delay();
}

