/* Variables: long, matching Scratch's number range — int is 16-bit on
 * sdcc/avr-gcc/cc65 and silently wraps mid-expression (76-multimeter). */
static long count = 0;

/* Register setup: ports, ADC, Timer 0. Kept out of main() so the program
 * body stands alone — a C -> blocks reader can then tell them apart. */
static void bw_setup(void)
{
    BW_VIA_ORA &= (uint8_t)~(1 << 0);      /* sda: start OFF */
    BW_VIA_DDRA |= (uint8_t)(1 << 0);   /* sda = PA0 output */
    BW_VIA_ORA &= (uint8_t)~(1 << 1);      /* scl: start OFF */
    BW_VIA_DDRA |= (uint8_t)(1 << 1);   /* scl = PA1 output */
    BW_VIA_ORA &= (uint8_t)~(1 << 2);      /* led: start OFF */
    BW_VIA_DDRA |= (uint8_t)(1 << 2);   /* led = PA2 output */
    BW_VIA_ACR = 0x40;             /* Timer 1 free-run */
    BW_VIA_T1CL = (uint8_t)(BW_T1_LATCH & 0xffu);
    BW_VIA_T1CH = (uint8_t)(BW_T1_LATCH >> 8);   /* load + start */
}

int main(void)
{
    bw_setup();

    bw_oled_clear(1);
    bw_oled_print_s(1, "6502 CALC");
    count = 0;
    for (;;) {
        bw_oled_cursor(1, 1, 0);
        if ((((BW_VIA_IRB >> 0) & 1) > 0)) {
            count += 1;
        }
        if ((((BW_VIA_IRB >> 1) & 1) > 0)) {
            count += -1;
        }
        if ((((BW_VIA_IRB >> 2) & 1) > 0)) {
            count = 0;
        }
        bw_oled_print_n(1, count);
        BW_VIA_ORA |= (uint8_t)(1 << 2);
        delay_ms(100);
        BW_VIA_ORA &= (uint8_t)~(1 << 2);
        delay_ms(100);
    }
}
